/**
 * Coverage of ntheory/factor.ts: multiplicity, perfect powers, factorint
 * and its methods, divisors and the classification of numbers, with the
 * expected values computed by SymPy 1.14 (Python's printed form).
 */

import { describe, expect, it } from 'vitest';
import { Expr } from '../src/core/nodes';
import { NoMatch, Unsolved } from '../src/core/truth';

/** Python's printed form of a result. */
function py(v: unknown): string {
  if (v === NoMatch || v === Unsolved || v === undefined || v === null) return 'None';
  if (v === true) return 'True';
  if (v === false) return 'False';
  if (typeof v === 'bigint' || typeof v === 'number' || typeof v === 'string') return String(v);
  if (v instanceof Expr) return v.toString();
  if (Array.isArray(v)) return `[${v.map(py).join(', ')}]`;
  if (v instanceof Map) return `{${[...v].map(([k, w]) => `${py(k)}: ${py(w)}`).join(', ')}}`;
  if (v instanceof Set) return `[${[...v].map(py).join(', ')}]`;
  return Object.prototype.toString.call(v);
}
import { Mul, Pow, Rational } from '../src/core/nodes';
import { fn } from '../src/functions/elementary';
import { abundance, divisorCount, divisors, factorint, factorrat, isAbundant, isDeficient, isPerfect, multiplicity, multiplicityInFactorial, perfectPower, pollardPm1, pollardRho, primefactors, properDivisorCount, smoothness, smoothnessP } from '../src/ntheory/index';
import { ecmOneFactor } from '../src/ntheory/factor';
import { factorCache } from '../src/ntheory/primetest';

